	periodTotal1 := sp.periodTotal1
	periodTotal2 := sp.periodTotal2
	prevDn := sp.prevDn
	prevUp := sp.prevUp
	shift := sp.shift
	trailingIdx := sp.trailingIdx
	windowStart := sp.windowStart
	pkSlot0 := int32(-1)
	var pkVal0 float64
	pkSlot0 = sp.today & sp.xMask
	pkVal0 = inReal
