// Value returns the value at the last bar of OutRange; Peek does not change it.
func (sp *RVIStream) Value() float64 {
	return sp.cur_outReal
}

// Clone returns an independent copy of the stream at the same bar: the two
// evolve separately and share only the [Core].
func (sp *RVIStream) Clone() *RVIStream {
	cl := *sp
	cl.x_inReal = append(sp.x_inReal[:0:0], sp.x_inReal...)
	return &cl
}

func (c *Core) rviOpenImpl(sp *RVIStream, inReal []float64, startIdx, optInTimePeriod, optInStdDevPeriod int32, outBegIdx, outNBElement *int32, outReal []float64, outStride int32) RetCode {
	var tempReal float64
	var shift float64
	var periodTotal1 float64
	var periodTotal2 float64
	var meanValue1 float64
	var variance float64
	var peakTotal2 float64
	var invPeriod float64
	var sigma float64
	var delta float64
	var upValue float64
	var dnValue float64
	var upTotal float64
	var dnTotal float64
	var prevUp float64
	var prevDn float64
	var wAlpha float64
	var wBeta float64
	var total float64
	var i int32
	var j int32
	var outIdx int32
	var today int32
	var anchorIdx int32
	var trailingIdx int32
	var windowStart int32
	var barsSinceReseed int32
	var nbInitialElementNeeded int32
	var lookbackTotal int32
	if len(inReal) > IndexMax+1 {
		return OutOfRangeEndIndex
	}
	historyLen := int32(len(inReal))
	endIdx := historyLen - 1
	if optInTimePeriod == IntegerDefault {
		optInTimePeriod = 14
	} else if optInTimePeriod < 1 || optInTimePeriod > 100000 {
		return BadParam
	}
	if optInStdDevPeriod == IntegerDefault {
		optInStdDevPeriod = 10
	} else if optInStdDevPeriod < 2 || optInStdDevPeriod > 100000 {
		return BadParam
	}
	if startIdx >= historyLen {
		*outBegIdx = 0
		*outNBElement = 0
		return InsufficientHistory
	}
	*outBegIdx = 0
	*outNBElement = 0
	lookbackTotal = c.rviLookback(optInTimePeriod, optInStdDevPeriod)
	if startIdx < lookbackTotal {
		startIdx = lookbackTotal
	}
	if startIdx > endIdx {
		return InsufficientHistory
	}
	wBeta = float64(optInTimePeriod-1) / float64(optInTimePeriod)
	wAlpha = 1.0 - wBeta
	nbInitialElementNeeded = optInStdDevPeriod - 1
	invPeriod = 1.0 / float64(optInStdDevPeriod)
	anchorIdx = startIdx - lookbackTotal
	trailingIdx = anchorIdx
	shift = inReal[anchorIdx]
	periodTotal1 = 0.0
	periodTotal2 = 0.0
	today = anchorIdx + nbInitialElementNeeded
	for j = anchorIdx; j < today; j += 1 {
		tempReal = inReal[j] - shift
		periodTotal1 += tempReal
		tempReal = float64(tempReal * tempReal)
		periodTotal2 += tempReal
	}
	barsSinceReseed = 32 * optInStdDevPeriod
	peakTotal2 = periodTotal2
	upTotal = 0.0
	dnTotal = 0.0
	for i = optInTimePeriod; i > 0; i -= 1 {
		tempReal = inReal[today] - shift
		periodTotal1 += tempReal
		tempReal = float64(tempReal * tempReal)
		periodTotal2 += tempReal
		var _T11 float64
		if periodTotal2 > peakTotal2 {
			_T11 = periodTotal2
		} else {
			_T11 = peakTotal2
		}
		peakTotal2 = _T11
		meanValue1 = float64(periodTotal1 * invPeriod)
		variance = float64(periodTotal2*invPeriod) - float64(meanValue1*meanValue1)
		tempReal = inReal[trailingIdx] - shift
		periodTotal1 -= tempReal
		tempReal = float64(tempReal * tempReal)
		periodTotal2 -= tempReal
		trailingIdx += 1
		barsSinceReseed -= 1
		if variance < float64(1e-6*float64(peakTotal2*invPeriod)) || barsSinceReseed <= 0 {
			barsSinceReseed = 32 * optInStdDevPeriod
			windowStart = today - nbInitialElementNeeded
			tempReal = 0.0
			for j = windowStart; j <= today; j += 1 {
				tempReal += inReal[j]
			}
			shift = float64(tempReal * invPeriod)
			periodTotal1 = 0.0
			periodTotal2 = 0.0
			for j = windowStart; j <= today; j += 1 {
				tempReal = inReal[j] - shift
				periodTotal1 += tempReal
				tempReal = float64(tempReal * tempReal)
				periodTotal2 += tempReal
			}
			meanValue1 = float64(periodTotal1 * invPeriod)
			variance = float64(periodTotal2*invPeriod) - float64(meanValue1*meanValue1)
			if variance < float64(1e-6*float64(periodTotal2*invPeriod)) {
				shift = inReal[today]
				periodTotal1 = 0.0
				periodTotal2 = 0.0
				for j = windowStart; j <= today; j += 1 {
					tempReal = inReal[j] - shift
					periodTotal1 += tempReal
					tempReal = float64(tempReal * tempReal)
					periodTotal2 += tempReal
				}
				meanValue1 = float64(periodTotal1 * invPeriod)
				variance = float64(periodTotal2*invPeriod) - float64(meanValue1*meanValue1)
			}
			peakTotal2 = periodTotal2
			if variance < float64(1e-12*float64(periodTotal2*invPeriod)) {
				variance = 0.0
			}
			tempReal = inReal[windowStart] - shift
			periodTotal1 -= tempReal
			tempReal = float64(tempReal * tempReal)
			periodTotal2 -= tempReal
		}
		sigma = math.Sqrt(variance)
		delta = inReal[today] - inReal[today-1]
		if delta > 0.0 {
			upTotal += sigma
		} else if delta < 0.0 {
			dnTotal += sigma
		}
		today += 1
	}
	prevUp = upTotal / float64(optInTimePeriod)
	prevDn = dnTotal / float64(optInTimePeriod)
	i = lookbackTotal - (optInStdDevPeriod - 1 + (optInTimePeriod - 1))
	for i != 0 {
		tempReal = inReal[today] - shift
		periodTotal1 += tempReal
		tempReal = float64(tempReal * tempReal)
		periodTotal2 += tempReal
		var _T12 float64
		if periodTotal2 > peakTotal2 {
			_T12 = periodTotal2
		} else {
			_T12 = peakTotal2
		}
		peakTotal2 = _T12
		meanValue1 = float64(periodTotal1 * invPeriod)
		variance = float64(periodTotal2*invPeriod) - float64(meanValue1*meanValue1)
		tempReal = inReal[trailingIdx] - shift
		periodTotal1 -= tempReal
		tempReal = float64(tempReal * tempReal)
		periodTotal2 -= tempReal
		trailingIdx += 1
		barsSinceReseed -= 1
		if variance < float64(1e-6*float64(peakTotal2*invPeriod)) || barsSinceReseed <= 0 {
			barsSinceReseed = 32 * optInStdDevPeriod
			windowStart = today - nbInitialElementNeeded
			tempReal = 0.0
			for j = windowStart; j <= today; j += 1 {
				tempReal += inReal[j]
			}
			shift = float64(tempReal * invPeriod)
			periodTotal1 = 0.0
			periodTotal2 = 0.0
			for j = windowStart; j <= today; j += 1 {
				tempReal = inReal[j] - shift
				periodTotal1 += tempReal
				tempReal = float64(tempReal * tempReal)
				periodTotal2 += tempReal
			}
			meanValue1 = float64(periodTotal1 * invPeriod)
			variance = float64(periodTotal2*invPeriod) - float64(meanValue1*meanValue1)
			if variance < float64(1e-6*float64(periodTotal2*invPeriod)) {
				shift = inReal[today]
				periodTotal1 = 0.0
				periodTotal2 = 0.0
				for j = windowStart; j <= today; j += 1 {
					tempReal = inReal[j] - shift
					periodTotal1 += tempReal
					tempReal = float64(tempReal * tempReal)
					periodTotal2 += tempReal
				}
				meanValue1 = float64(periodTotal1 * invPeriod)
				variance = float64(periodTotal2*invPeriod) - float64(meanValue1*meanValue1)
			}
			peakTotal2 = periodTotal2
			if variance < float64(1e-12*float64(periodTotal2*invPeriod)) {
				variance = 0.0
			}
			tempReal = inReal[windowStart] - shift
			periodTotal1 -= tempReal
			tempReal = float64(tempReal * tempReal)
			periodTotal2 -= tempReal
		}
		sigma = math.Sqrt(variance)
		delta = inReal[today] - inReal[today-1]
		upValue = 0.0
		dnValue = 0.0
		if delta > 0.0 {
			upValue = sigma
		} else if delta < 0.0 {
			dnValue = sigma
		}
		prevUp = math.FMA(wBeta, prevUp, float64(wAlpha*upValue))
		prevDn = math.FMA(wBeta, prevDn, float64(wAlpha*dnValue))
		today += 1
		i -= 1
	}
	total = prevUp + prevDn
	var _T13 float64
	if total == 0.0 {
		_T13 = 50.0
	} else {
		_T13 = float64(100.0 * (prevUp / total))
	}
	outReal[0*outStride] = _T13
	outIdx = 1
	for today <= endIdx {
		tempReal = inReal[today] - shift
		periodTotal1 += tempReal
		tempReal = float64(tempReal * tempReal)
		periodTotal2 += tempReal
		peakTotal2 = selF(periodTotal2 > peakTotal2, periodTotal2, peakTotal2)
		meanValue1 = float64(periodTotal1 * invPeriod)
		variance = float64(periodTotal2*invPeriod) - float64(meanValue1*meanValue1)
		tempReal = inReal[trailingIdx] - shift
		periodTotal1 -= tempReal
		tempReal = float64(tempReal * tempReal)
		periodTotal2 -= tempReal
		trailingIdx += 1
		barsSinceReseed -= 1
		if variance < float64(1e-6*float64(peakTotal2*invPeriod)) || barsSinceReseed <= 0 {
			barsSinceReseed = 32 * optInStdDevPeriod
			windowStart = today - nbInitialElementNeeded
			tempReal = 0.0
			for j = windowStart; j <= today; j += 1 {
				tempReal += inReal[j]
			}
			shift = float64(tempReal * invPeriod)
			periodTotal1 = 0.0
			periodTotal2 = 0.0
			for j = windowStart; j <= today; j += 1 {
				tempReal = inReal[j] - shift
				periodTotal1 += tempReal
				tempReal = float64(tempReal * tempReal)
				periodTotal2 += tempReal
			}
			meanValue1 = float64(periodTotal1 * invPeriod)
			variance = float64(periodTotal2*invPeriod) - float64(meanValue1*meanValue1)
			if variance < float64(1e-6*float64(periodTotal2*invPeriod)) {
				shift = inReal[today]
				periodTotal1 = 0.0
				periodTotal2 = 0.0
				for j = windowStart; j <= today; j += 1 {
					tempReal = inReal[j] - shift
					periodTotal1 += tempReal
					tempReal = float64(tempReal * tempReal)
					periodTotal2 += tempReal
				}
				meanValue1 = float64(periodTotal1 * invPeriod)
				variance = float64(periodTotal2*invPeriod) - float64(meanValue1*meanValue1)
			}
			peakTotal2 = periodTotal2
			if variance < float64(1e-12*float64(periodTotal2*invPeriod)) {
				variance = 0.0
			}
			tempReal = inReal[windowStart] - shift
			periodTotal1 -= tempReal
			tempReal = float64(tempReal * tempReal)
			periodTotal2 -= tempReal
		}
		sigma = math.Sqrt(variance)
		delta = inReal[today] - inReal[today-1]
		upValue = 0.0
		dnValue = 0.0
		if delta > 0.0 {
			upValue = sigma
		} else if delta < 0.0 {
			dnValue = sigma
		}
		prevUp = math.FMA(wBeta, prevUp, float64(wAlpha*upValue))
		prevDn = math.FMA(wBeta, prevDn, float64(wAlpha*dnValue))
		total = prevUp + prevDn
		var _T14 float64
		if total == 0.0 {
			_T14 = 50.0
		} else {
			_T14 = float64(100.0 * (prevUp / total))
		}
		outReal[outIdx*outStride] = _T14
		outIdx++
		today += 1
	}
	*outBegIdx = startIdx
	*outNBElement = outIdx
	capX := today - trailingIdx + 1
	if capX < 1 || capX > historyLen {
		return InternalError
	}
	physX := int32(1)
	for physX < capX {
		physX <<= 1
	}
	capX_inReal := make([]float64, physX)
	for fillJ := historyLen - capX; fillJ < historyLen; fillJ++ {
		capX_inReal[fillJ&(physX-1)] = inReal[fillJ]
	}
	sp.optInTimePeriod = optInTimePeriod
	sp.optInStdDevPeriod = optInStdDevPeriod
	sp.shift = shift
	sp.periodTotal1 = periodTotal1
	sp.periodTotal2 = periodTotal2
	sp.peakTotal2 = peakTotal2
	sp.invPeriod = invPeriod
	sp.prevUp = prevUp
	sp.prevDn = prevDn
	sp.wAlpha = wAlpha
	sp.wBeta = wBeta
	sp.trailingIdx = trailingIdx
	sp.barsSinceReseed = barsSinceReseed
	sp.nbInitialElementNeeded = nbInitialElementNeeded
	sp.j = j
	sp.windowStart = windowStart
	sp.today = today
	sp.lag1_inReal = inReal[historyLen-1]
	sp.xMask = physX - 1
	sp.x_inReal = capX_inReal
	sp.cur_outReal = outReal[(*outNBElement-1)*outStride]
	return Success
}

func (c *Core) rviOpenAndFillInternal(inReal []float64, startIdx, optInTimePeriod, optInStdDevPeriod int32, outBegIdx, outNBElement *int32, outReal []float64) (*RVIStream, error) {
	sp := &RVIStream{core: c}
	if retCode := c.rviOpenImpl(sp, inReal, startIdx, optInTimePeriod, optInStdDevPeriod, outBegIdx, outNBElement, outReal, 1); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(*outBegIdx)
	sp.outRangeCount = int(*outNBElement)
	return sp, nil
}

func (c *Core) rviOpenInternal(inReal []float64, startIdx, optInTimePeriod, optInStdDevPeriod int32) (*RVIStream, error) {
	sp := &RVIStream{core: c}
	var outBegIdx, outNBElement int32
	var sink_outReal [1]float64
	if retCode := c.rviOpenImpl(sp, inReal, startIdx, optInTimePeriod, optInStdDevPeriod, &outBegIdx, &outNBElement, sink_outReal[:], 0); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(outBegIdx)
	sp.outRangeCount = int(outNBElement)
	return sp, nil
}

// RVIOpen opens a live [RVIStream] on a warm-up history, oldest bar first, and
// returns it with its value at the last history bar, the value [Core.RVI]
// writes there.
//
// inReal is the history; the parameters are those of [Core.RVI].
//
// The error is [InsufficientHistory] for a history of at most
// [Core.RVILookback] bars, [OutOfRangeEndIndex] for one longer than
// [IndexMax]+1 bars, and [BadParam] for a parameter out of range.
func (c *Core) RVIOpen(inReal []float64, optInTimePeriod, optInStdDevPeriod int) (*RVIStream, float64, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, 0, BadParam
	}
	if !fitsInt32(optInStdDevPeriod) {
		return nil, 0, BadParam
	}
	sp, err := c.rviOpenInternal(inReal, 0, int32(optInTimePeriod), int32(optInStdDevPeriod))
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outReal, nil
}

// RVIOpenAndFill opens a stream as [Core.RVIOpen] does and also writes the
// outputs over the whole history, as [Core.RVI] writes them for bars 0 through
// len(inReal)-1, returning that range.
//
// Each output must hold len(inReal) minus [Core.RVILookback] values and share
// no memory with an input or another output.
//
// The errors are those of [Core.RVIOpen], and [BadParam] for an output that is
// empty, too short or sharing memory. A slice whose capacity a three-index
// expression cut, as slices.Clip does, can escape the sharing check.
func (c *Core) RVIOpenAndFill(inReal []float64, optInTimePeriod, optInStdDevPeriod int, outReal []float64) (*RVIStream, OutRange, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, OutRange{}, BadParam
	}
	if !fitsInt32(optInStdDevPeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inReal) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.rviLookback(int32(optInTimePeriod), int32(optInStdDevPeriod)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inReal)-lookback, 0)
	if len(outReal) == 0 || len(outReal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && overlaps(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.rviOpenAndFillInternal(inReal, 0, int32(optInTimePeriod), int32(optInStdDevPeriod), &outBegIdx, &outNBElement, outReal)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
